npm ci && printf '{"a":1}
{"b":[1,2]}
{"c":"x"}
' > /tmp/ok.jsonl && npx jsonl-lint /tmp/ok.jsonl > /tmp/out.txt 2>&1; echo exit=$?; grep -c '^/tmp/ok.jsonl:[0-9]*:' /tmp/out.txt  # expect exit=0 and count 0

printf '{"a":1}
{bad
{"b":2}
{"c": 3,}
[1]
{"torn":"x' > /tmp/bad.jsonl && npx jsonl-lint /tmp/bad.jsonl > /tmp/out.txt 2>&1; echo exit=$?; for n in 1 2 3 4 5 6; do echo "$n: $(grep -c "^/tmp/bad.jsonl:$n:" /tmp/out.txt)"; done  # expect exit non-zero; counts 1:0 2:1 3:0 4:1 5:0 6:1
